14	
15	public sealed record Actor(Guid Id, string Name, UserRole Role, Guid? CourseId, Guid? ResearchLabId);
16	
17	/// <summary>
18	/// Authentication is out of scope, so callers identify themselves with one of the seeded
19	/// mock users in the X-User-Id header. Missing or unknown ids get 401; the wrong role gets 403.
20	/// </summary>
21	public static class Actors
22	{
23	    public const string Header = "X-User-Id";
24	
25	    public static async Task<(Actor? Actor, IResult? Error)> RequireAsync(
26	        HttpContext http, HubDbContext db, CancellationToken ct, params UserRole[] allowed)
27	    {
28	        var raw = http.Request.Headers[Header].ToString();
29	        if (!Guid.TryParse(raw, out var userId))
30	        {
31	            return (null, Problems.Unauthorized($"Send the id of a known user in the {Header} header."));
32	        }
33	
34	        var user = await db.Users.AsNoTracking().FirstOrDefaultAsync(u => u.Id == userId, ct);
35	        if (user is null)
36	        {
37	            return (null, Problems.Unauthorized($"The {Header} header does not name a known user."));
38	        }
39	
40	        var actor = new Actor(user.Id, user.Name, user.Role, user.CourseId, user.ResearchLabId);
41	        if (allowed.Length > 0 && !allowed.Contains(user.Role))
42	        {
43	            return (actor, Problems.Forbidden($"This action needs one of these roles: {string.Join(", ", allowed)}."));
44	        }
45	
46	        return (actor, null);
47	    }
48	}
