   107	    /// <summary>
   108	    /// pending -> approved | rejected (IT director sign-off) and allocated -> closed (administrator).
   109	    /// approved -> allocated only happens through POST .../allocate (spec 6.8).
   110	    /// </summary>
   111	    private static async Task<IResult> TransitionAsync(
   112	        Guid ticketId, TicketStatus target, string? reason, Actor actor, HubDbContext db, TimeProvider clock, ILogger log, CancellationToken ct)
   113	    {
   114	        var errors = new Errors();
   115	        reason = Validation.Text(errors, "reason", reason, 500, required: false);
   116	        if (errors.Any)
   117	        {
   118	            return errors.ToResult();
   119	        }
   120	
   121	        await using var tx = await db.Database.BeginTransactionAsync(ct);
   122	        var ticket = await LockTicketAsync(db, ticketId, ct);
   123	        if (ticket is null)
   124	        {
   125	            return Problems.NotFound("Ticket not found.");
   126	        }
   127	
   128	        TicketStatus requiredFrom;
   129	        UserRole requiredRole;
   130	        TicketEventType eventType;
   131	        switch (target)
   132	        {
   133	            case TicketStatus.Approved:
   134	                (requiredFrom, requiredRole, eventType) = (TicketStatus.Pending, UserRole.ItDirector, TicketEventType.Approved);
   135	                break;
   136	            case TicketStatus.Rejected:
   137	                (requiredFrom, requiredRole, eventType) = (TicketStatus.Pending, UserRole.ItDirector, TicketEventType.Rejected);
   138	                break;
   139	            case TicketStatus.Closed:
   140	                (requiredFrom, requiredRole, eventType) = (TicketStatus.Allocated, UserRole.Administrator, TicketEventType.Closed);
   141	                break;
   142	            case TicketStatus.Allocated:
   143	                return Problems.Conflict("Use the allocate command.", "Tickets become allocated only through POST /api/v1/assets/tickets/{ticket_id}/allocate.");
   144	            default:
   145	                return Problems.Conflict("Tickets cannot move back to pending.");
   146	        }
   147	
   148	        if (actor.Role != requiredRole)
   149	        {
   150	            return Problems.Forbidden($"Moving a ticket to {Lower(target)} needs the {requiredRole} role.");
   151	        }
   152	        if (ticket.Status != requiredFrom)
   153	        {
   154	            return Problems.Conflict($"Cannot move a {Lower(ticket.Status)} ticket to {Lower(target)}.",
   155	                $"Only {Lower(requiredFrom)} tickets can move to {Lower(target)}.");
   156	        }
   157	
   158	        var now = clock.GetUtcNow();
   159	        var from = ticket.Status;
   160	        ticket.Status = target;
   161	        ticket.UpdatedAt = now;
   162	        switch (target)
   163	        {
   164	            case TicketStatus.Approved: ticket.ApprovedAt = now; break;
   165	            case TicketStatus.Rejected: ticket.RejectedAt = now; break;
   166	            case TicketStatus.Closed: ticket.ClosedAt = now; break;
   167	        }
   168	        db.TicketEvents.Add(TicketEvents.Create(ticketId, eventType, from, target, actor.Id, now, reason));
   169	        await db.SaveChangesAsync(ct);
   170	        await tx.CommitAsync(ct);
   171	        log.LogInformation("Ticket {TicketId} moved from {From} to {To} by {ActorId}", ticketId, from, target, actor.Id);
   172	
   173	        var saved = await WithItems(db).AsNoTracking().FirstAsync(t => t.Id == ticketId, ct);
   174	        return Results.Ok(TicketViews.ToDto(saved));
   175	    }
