   217	        foreach (var part in (status ?? "").Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
   218	        {
   219	            if (Query.Enum<TicketStatus>(errors, "status", part) is { } parsed)
   220	            {
   221	                statuses.Add(parsed);
   222	            }
   223	        }
   224	        var (p, size) = Query.Paging(errors, page, pageSize);
   225	        if (errors.Any)
