    16	public sealed record ValidTicketContent(
    17	    Guid? CourseId, Guid? ResearchLabId, Guid? ProjectId, string? Notes, List<TicketItem> Items);
    18	
    19	public static class TicketContent
    20	{
    21	    public const int MaxItems = 20;
    22	    public const int MaxQuantity = 1_000;
    23	
    24	    /// <summary>Returns the cleaned content, or a 400/403 result.</summary>
    25	    public static async Task<(ValidTicketContent? Content, IResult? Error)> ValidateAsync(
    26	        HubDbContext db, Actor requester, TicketRequest body, CancellationToken ct)
    27	    {
    28	        var errors = new Errors();
    29	
    30	        if (body.Status is not null || body.Reason is not null)
    31	        {
    32	            errors.Add("status", "Status changes are a separate PUT on the ticket and cannot be combined with content.");
    33	        }
    34	        if ((body.CourseId is null) == (body.ResearchLabId is null))
    35	        {
    36	            errors.Add("courseId", "Give exactly one of courseId or researchLabId.");
    37	        }
    38	        var notes = Validation.Text(errors, "notes", body.Notes, 2000, required: false);
    39	
    40	        var items = new List<TicketItem>();
    41	        if (body.Items is null || body.Items.Count == 0)
    42	        {
    43	            errors.Add("items", "Request at least one asset.");
    44	        }
    45	        else if (body.Items.Count > MaxItems)
    46	        {
    47	            errors.Add("items", $"At most {MaxItems} assets per ticket.");
    48	        }
    49	        else
    50	        {
    51	            var ids = body.Items.Where(i => i.AssetId is not null).Select(i => i.AssetId!.Value).ToList();
    52	            if (ids.Count != ids.Distinct().Count())
    53	            {
    54	                errors.Add("items", "Each asset can appear only once; combine the quantities.");
    55	            }
    56	            var assets = await db.Assets.AsNoTracking().Where(a => ids.Contains(a.Id)).ToDictionaryAsync(a => a.Id, ct);
    57	
    58	            for (var n = 0; n < body.Items.Count; n++)
    59	            {
    60	                var item = body.Items[n];
    61	                var field = $"items[{n}]";
    62	                if (item.AssetId is null || !assets.TryGetValue(item.AssetId.Value, out var asset))
    63	                {
    64	                    errors.Add($"{field}.assetId", "Unknown asset.");
    65	                    continue;
    66	                }
    67	
    68	                if (asset.Type == AssetType.Voucher)
    69	                {
    70	                    Validation.Money(errors, $"{field}.amount", item.Amount);
    71	                    if (item.Quantity is not null)
    72	                    {
    73	                        errors.Add($"{field}.quantity", "Voucher assets take an amount, not a quantity.");
    74	                    }
    75	                }
    76	                else
    77	                {
    78	                    if (item.Quantity is null || item.Quantity < 1 || item.Quantity > MaxQuantity)
    79	                    {
    80	                        errors.Add($"{field}.quantity", $"Must be between 1 and {MaxQuantity}.");
    81	                    }
    82	                    if (item.Amount is not null)
    83	                    {
    84	                        errors.Add($"{field}.amount", "Physical and license assets take a quantity, not an amount.");
    85	                    }
    86	                }
    87	
    88	                if (asset.Type == AssetType.Physical)
    89	                {
    90	                    Validation.LoanDays(errors, $"{field}.loanDays", item.LoanDays, required: false);
    91	                }
    92	                else if (item.LoanDays is not null)
    93	                {
    94	                    errors.Add($"{field}.loanDays", "Only physical assets have a loan period.");
    95	                }
    96	
    97	                items.Add(new TicketItem
    98	                {
    99	                    Id = Guid.NewGuid(),
   100	                    AssetId = asset.Id,
   101	                    Quantity = item.Quantity,
   102	                    Amount = item.Amount,
   103	                    LoanDays = item.LoanDays,
   104	                });
   105	            }
   106	        }
   107	
   108	        if (body.ProjectId is not null)
   109	        {
   110	            var project = await db.Projects.AsNoTracking().FirstOrDefaultAsync(p => p.Id == body.ProjectId, ct);
   111	            if (project is null)
   112	            {
   113	                errors.Add("projectId", "Unknown project.");
   114	            }
   115	            else if (project.CourseId != body.CourseId || project.ResearchLabId != body.ResearchLabId)
   116	            {
   117	                errors.Add("projectId", "The project belongs to a different course or research lab.");
   118	            }
   119	        }
   120	
   121	        if (errors.Any)
   122	        {
   123	            return (null, errors.ToResult());
   124	        }
   125	
   126	        // Instructors ask for their own course, lab advisors for their own lab.
   127	        var allowed = requester.Role switch
   128	        {
   129	            UserRole.CourseInstructor => body.CourseId is not null && body.CourseId == requester.CourseId,
   130	            UserRole.LabAdvisor => body.ResearchLabId is not null && body.ResearchLabId == requester.ResearchLabId,
   131	            _ => false,
   132	        };
   133	        if (!allowed)
   134	        {
   135	            return (null, Problems.Forbidden("Course instructors request for their own course and lab advisors for their own research lab."));
   136	        }
   137	
   138	        return (new ValidTicketContent(body.CourseId, body.ResearchLabId, body.ProjectId, notes, items), null);
   139	    }
   140	}

