   210	    private static async Task<IResult> ListAsync(
   211	        HubDbContext db, CancellationToken ct,
   212	        string? status = null, string? assetCategory = null, Guid? courseId = null, Guid? researchLabId = null,
   213	        Guid? projectId = null, int? page = null, int? pageSize = null)
   214	    {
   215	        var errors = new Errors();
   216	        var statuses = new List<TicketStatus>();
   217	        foreach (var part in (status ?? "").Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
   218	        {
   219	            if (Query.Enum<TicketStatus>(errors, "status", part) is { } parsed)
   220	            {
   221	                statuses.Add(parsed);
   222	            }
   223	        }
   224	        var (p, size) = Query.Paging(errors, page, pageSize);
   225	        if (errors.Any)
   226	        {
   227	            return errors.ToResult();
   228	        }
   229	
   230	        var q = db.Tickets.AsNoTracking();
   231	        if (statuses.Count > 0)
   232	        {
   233	            q = q.Where(t => statuses.Contains(t.Status));
   234	        }
   235	        if (courseId is not null)
   236	        {
   237	            q = q.Where(t => t.CourseId == courseId);
   238	        }
   239	        if (researchLabId is not null)
   240	        {
   241	            q = q.Where(t => t.ResearchLabId == researchLabId);
   242	        }
   243	        if (projectId is not null)
   244	        {
   245	            q = q.Where(t => t.ProjectId == projectId);
   246	        }
   247	        if (!string.IsNullOrWhiteSpace(assetCategory))
   248	        {
   249	            var c = assetCategory.Trim().ToLower();
   250	            q = q.Where(t => t.Items.Any(i => i.Asset!.Category.ToLower() == c));
   251	        }
   252	
   253	        var total = await q.CountAsync(ct);
   254	        var ids = await q
   255	            .OrderByDescending(t => t.CreatedAt).ThenBy(t => t.Id)
   256	            .Skip((p - 1) * size).Take(size)
   257	            .Select(t => t.Id)
   258	            .ToListAsync(ct);
   259	        var rows = await WithItems(db).AsNoTracking().Where(t => ids.Contains(t.Id)).ToListAsync(ct);
   260	        var ordered = ids.Select(id => TicketViews.ToDto(rows.Single(t => t.Id == id))).ToList();
   261	
   262	        return Results.Ok(new PagedResult<TicketDto>(ordered, p, size, total));
   263	    }
