    89	
    90	            List<string>? keys = null;
    91	            List<DeviceDto>? devices = null;
    92	            switch (asset.Type)
    93	            {
    94	                case AssetType.Physical:
    95	                    {
    96	                        var qty = item.Quantity!.Value;
    97	                        asset.RemainingUnits -= qty;
    98	                        var due = now.AddDays(item.LoanDays ?? asset.DefaultLoanDays!.Value);
    99	                        devices = [];
   100	                        for (var n = 0; n < qty; n++)
   101	                        {
   102	                            var token = NewToken();
   103	                            db.DeviceAssignments.Add(new DeviceAssignment
   104	                            {
   105	                                Id = Guid.NewGuid(),
   106	                                Token = token,
   107	                                AllocationId = allocation.Id,
   108	                                AssetId = asset.Id,
   109	                                TicketId = ticketId,
   110	                                CheckedOutAt = now,
   111	                                DueAt = due,
   112	                            });
   113	                            devices.Add(new DeviceDto(token, now, due, null, "checkedout"));
   114	                        }
   115	                        break;
   116	                    }
   117	                case AssetType.License:
   118	                    {
   119	                        var qty = item.Quantity!.Value;
   120	                        var free = await db.LicenseKeys
   121	                            .Where(k => k.AssetId == asset.Id && k.IssuedTicketId == null)
   122	                            .OrderBy(k => k.Id)
