604	    19	    public static async Task<List<AssetDto>> ToDtosAsync(
605	    20	        HubDbContext db, IReadOnlyList<Asset> assets, DateTimeOffset now, CancellationToken ct)
606	    21	    {
607	    22	        var physicalIds = assets.Where(a => a.Type == AssetType.Physical).Select(a => a.Id).ToList();
608	    23	
609	    24	        // Reserved: units requested on approved tickets that have not been allocated yet.
610	    25	        var reserved = await db.TicketItems
611	    26	            .Where(i => physicalIds.Contains(i.AssetId)
612	    27	                        && db.Tickets.Any(t => t.Id == i.TicketId && t.Status == TicketStatus.Approved))
613	    28	            .GroupBy(i => i.AssetId)
614	    29	            .Select(g => new { AssetId = g.Key, Units = g.Sum(i => i.Quantity ?? 0) })
615	    30	            .ToDictionaryAsync(x => x.AssetId, x => x.Units, ct);
616	    31	
617	    32	        var outstanding = await db.DeviceAssignments
618	    33	            .Where(d => physicalIds.Contains(d.AssetId) && d.ReturnedAt == null)
619	    34	            .GroupBy(d => d.AssetId)
620	    35	            .Select(g => new
621	    36	            {
622	    37	                AssetId = g.Key,
623	    38	                Overdue = g.Count(d => d.DueAt < now),
624	    39	                CheckedOut = g.Count(d => d.DueAt >= now),
625	    40	            })
626	    41	            .ToDictionaryAsync(x => x.AssetId, ct);
627	    42	
628	    43	        return assets.Select(a =>
629	    44	        {
630	    45	            var counts = outstanding.GetValueOrDefault(a.Id);
631	    46	            return ToDto(a, reserved.GetValueOrDefault(a.Id), counts?.CheckedOut ?? 0, counts?.Overdue ?? 0);
632	    47	        }).ToList();
