647	    62	                    Available: a.RemainingUnits ?? 0,
648	    63	                    Reserved: reserved,
649	    64	                    Checkedout: checkedOut,
650	    65	                    Overdue: overdue)),
651	    66	            AssetType.License => (
652	    67	                (decimal)(a.TotalUnits ?? 0),
653	    68	                (decimal)(a.RemainingUnits ?? 0),
654	    69	                new AvailabilityDto(
655	    70	                    IsAvailable: a.RemainingUnits > 0,
