    24	    /// <summary>
    25	    /// Active means (spec 6.12): physical devices not yet returned, and license and voucher
    26	    /// allocations whose ticket is not closed. Issued license keys are shown, so only the
    27	    /// group's own requester role, the IT director and administrators may read this.
    28	    /// </summary>
    29	    private static async Task<IResult> ListActiveAsync(
    30	        HttpContext http, HubDbContext db, TimeProvider clock, CancellationToken ct,
    31	        Guid? courseId = null, Guid? researchLabId = null)
    32	    {
    33	        var (actor, denied) = await Actors.RequireAsync(http, db, ct);
    34	        if (denied is not null)
    35	        {
    36	            return denied;
    37	        }
    38	
    39	        if ((courseId is null) == (researchLabId is null))
    40	        {
    41	            return Problems.BadRequest("courseId", "Give exactly one of courseId or researchLabId.");
    42	        }
    43	        var exists = courseId is not null
    44	            ? await db.Courses.AnyAsync(c => c.Id == courseId, ct)
    45	            : await db.ResearchLabs.AnyAsync(l => l.Id == researchLabId, ct);
    46	        if (!exists)
    47	        {
    48	            return Problems.BadRequest(courseId is not null ? "courseId" : "researchLabId", "Unknown course or research lab.");
    49	        }
    50	
    51	        var allowed = actor!.Role switch
    52	        {
    53	            UserRole.Administrator or UserRole.ItDirector => true,
    54	            UserRole.CourseInstructor => courseId is not null && actor.CourseId == courseId,
    55	            UserRole.LabAdvisor => researchLabId is not null && actor.ResearchLabId == researchLabId,
    56	            _ => false,
    57	        };
    58	        if (!allowed)
    59	        {
    60	            return Problems.Forbidden("Only the course's instructor, the lab's advisor, the IT director or an administrator can read these allocations.");
    61	        }
    62	
    63	        var rows = await db.Allocations.AsNoTracking()
    64	            .Include(a => a.Asset)
    65	            .Include(a => a.Devices.Where(d => d.ReturnedAt == null))
    66	            .Include(a => a.LicenseKeys)
    67	            .Where(a => courseId != null ? a.Ticket!.CourseId == courseId : a.Ticket!.ResearchLabId == researchLabId)
    68	            .Where(a => a.AssetType == AssetType.Physical
    69	                ? a.Devices.Any(d => d.ReturnedAt == null)
    70	                : a.Ticket!.Status != TicketStatus.Closed)
    71	            .OrderByDescending(a => a.AllocatedAt).ThenBy(a => a.Id)
    72	            .AsSplitQuery()
    73	            .ToListAsync(ct);
    74	
    75	        var now = clock.GetUtcNow();
    76	        var allocations = rows.Select(a => new AllocationDto(
    77	            a.Id, a.TicketId, a.AssetId, a.Asset!.Name, a.AssetType, a.Asset.Category, a.AllocatedAt,
    78	            a.Quantity, a.Amount,
    79	            a.AssetType == AssetType.License ? a.LicenseKeys.Select(k => k.Key).Order(StringComparer.Ordinal).ToList() : null,
    80	            a.AssetType == AssetType.Physical
    81	                ? a.Devices.OrderBy(d => d.Token, StringComparer.Ordinal)
    82	                    .Select(d => new DeviceDto(d.Token, d.CheckedOutAt, d.DueAt, null, d.DueAt < now ? "overdue" : "checkedout"))
    83	                    .ToList()
    84	                : null)).ToList();
    85	
    86	        var devices = allocations.SelectMany(a => a.Devices ?? []).ToList();
    87	        var summary = new AllocationSummaryDto(
    88	            DevicesCheckedOut: devices.Count,
    89	            DevicesOverdue: devices.Count(d => d.Status == "overdue"),
    90	            LicenseKeysAssigned: allocations.Sum(a => a.LicenseKeys?.Count ?? 0),
    91	            VoucherCreditsAllocated: allocations.Where(a => a.AssetType == AssetType.Voucher).Sum(a => a.Amount ?? 0m));
    92	
    93	        return Results.Ok(new ActiveAllocationsDto(courseId, researchLabId, summary, allocations));
    94	    }
    95	}
