     9	using System.Security.Cryptography;
    10	using Microsoft.EntityFrameworkCore;
    11	using ResourceHub.Api.Contracts;
    12	using ResourceHub.Api.Data;
    13	using ResourceHub.Api.Domain;
    14	
    15	namespace ResourceHub.Api.Services;
    16	
    17	/// <summary>
    18	/// Runs POST /api/v1/assets/tickets/{id}/allocate (requirement 4, spec 6.9 and 6.10).
    19	/// The ticket row and the requested asset rows are locked (in asset id order, so two
    20	/// allocations cannot deadlock) for one transaction. Stock is checked for every item
    21	/// before anything changes; if any item is short, nothing is written except a failure event.
    22	/// </summary>
    23	public sealed class AllocationService
    24	{
    25	    private readonly HubDbContext db;
    26	    private readonly TimeProvider clock;
    27	    private readonly ILogger<AllocationService> log;
    28	
    29	    public AllocationService(HubDbContext db, TimeProvider clock, ILogger<AllocationService> log)
    30	    {
    31	        this.db = db;
    32	        this.clock = clock;
    33	        this.log = log;
    34	    }
    35	
    36	    public async Task<IResult> AllocateAsync(Guid ticketId, Actor actor, CancellationToken ct)
    37	    {
    38	        var now = clock.GetUtcNow();
    39	        await using var tx = await db.Database.BeginTransactionAsync(ct);
    40	
    41	        var ticket = await db.Tickets
    42	            .FromSql($"SELECT * FROM tickets WHERE \"Id\" = {ticketId} FOR UPDATE")
    43	            .FirstOrDefaultAsync(ct);
    44	        if (ticket is null)
    45	        {
    46	            return Problems.NotFound("Ticket not found.");
    47	        }
    48	
    49	        if (ticket.Status != TicketStatus.Approved)
    50	        {
    51	            var status = ticket.Status.ToString().ToLowerInvariant();
    52	            await RecordFailureAsync(tx, ticket, actor, now, $"Ticket is {status}, not approved.", ct);
    53	            return Problems.Conflict("Only approved tickets can be allocated.", $"The ticket is {status}.");
    54	        }
    55	
    56	        var items = await db.TicketItems.AsNoTracking().Where(i => i.TicketId == ticketId).ToListAsync(ct);
    57	        var assetIds = items.Select(i => i.AssetId).Distinct().OrderBy(id => id).ToArray();
    58	        var assets = await db.Assets
    59	            .FromSql($"SELECT * FROM assets WHERE \"Id\" = ANY({assetIds}) ORDER BY \"Id\" FOR UPDATE")
    60	            .ToDictionaryAsync(a => a.Id, ct);
    61	
    62	        var shortages = FindShortages(items, assets);
    63	        if (shortages.Count > 0)
    64	        {
    65	            var detail = string.Join("; ", shortages.Select(s => $"{s.AssetName}: requested {s.Requested}, available {s.Available}"));
    66	            await RecordFailureAsync(tx, ticket, actor, now, "Not enough stock. " + detail, ct);
    67	            log.LogWarning("Allocation of ticket {TicketId} failed for lack of stock on {ShortCount} asset(s)", ticketId, shortages.Count);
    68	            return Problems.Conflict(
    69	                "Not enough stock to allocate this ticket.",
    70	                "Nothing was allocated; the ticket stays approved and allocation can be run again later.",
    71	                new Dictionary<string, object?> { ["shortages"] = shortages });
    72	        }
    73	
    74	        var results = new List<AllocationDto>();
    75	        foreach (var item in items.OrderBy(i => assets[i.AssetId].Name).ThenBy(i => i.AssetId))
    76	        {
    77	            var asset = assets[item.AssetId];
    78	            var allocation = new Allocation
    79	            {
    80	                Id = Guid.NewGuid(),
    81	                TicketId = ticketId,
    82	                AssetId = asset.Id,
    83	                AssetType = asset.Type,
    84	                Quantity = item.Quantity,
    85	                Amount = item.Amount,
    86	                AllocatedAt = now,
    87	            };
    88	            db.Allocations.Add(allocation);
    89	
    90	            List<string>? keys = null;
    91	            List<DeviceDto>? devices = null;
    92	            switch (asset.Type)
    93	            {
    94	                case AssetType.Physical:
    95	                    {
    96	                        var qty = item.Quantity!.Value;
    97	                        asset.RemainingUnits -= qty;
    98	                        var due = now.AddDays(item.LoanDays ?? asset.DefaultLoanDays!.Value);
    99	                        devices = [];
   100	                        for (var n = 0; n < qty; n++)
   101	                        {
   102	                            var token = NewToken();
   103	                            db.DeviceAssignments.Add(new DeviceAssignment
   104	                            {
   105	                                Id = Guid.NewGuid(),
   106	                                Token = token,
   107	                                AllocationId = allocation.Id,
   108	                                AssetId = asset.Id,
   109	                                TicketId = ticketId,
   110	                                CheckedOutAt = now,
   111	                                DueAt = due,
   112	                            });
   113	                            devices.Add(new DeviceDto(token, now, due, null, "checkedout"));
   114	                        }
   115	                        break;
   116	                    }
   117	                case AssetType.License:
   118	                    {
   119	                        var qty = item.Quantity!.Value;
   120	                        var free = await db.LicenseKeys
   121	                            .Where(k => k.AssetId == asset.Id && k.IssuedTicketId == null)
   122	                            .OrderBy(k => k.Id)
   123	                            .Take(qty)
   124	                            .ToListAsync(ct);
   125	                        foreach (var key in free)
   126	                        {
   127	                            key.IssuedTicketId = ticketId;
   128	                            key.AllocationId = allocation.Id;
   129	                            key.IssuedAt = now;
   130	                        }
   131	                        asset.RemainingUnits -= qty;
   132	                        keys = free.Select(k => k.Key).ToList();
   133	                        break;
   134	                    }
   135	                case AssetType.Voucher:
   136	                    asset.Balance -= item.Amount!.Value;
   137	                    break;
   138	            }
   139	            asset.UpdatedAt = now;
   140	
   141	            results.Add(new AllocationDto(
   142	                allocation.Id, ticketId, asset.Id, asset.Name, asset.Type, asset.Category, now,
   143	                allocation.Quantity, allocation.Amount, keys, devices));
   144	        }
   145	
   146	        ticket.Status = TicketStatus.Allocated;
   147	        ticket.AllocatedAt = now;
   148	        ticket.UpdatedAt = now;
   149	        db.TicketEvents.Add(TicketEvents.Create(ticketId, TicketEventType.AllocationSucceeded,
   150	            TicketStatus.Approved, TicketStatus.Allocated, actor.Id, now, $"{results.Count} asset(s) allocated"));
   151	
   152	        await db.SaveChangesAsync(ct);
   153	        await tx.CommitAsync(ct);
   154	        log.LogInformation("Ticket {TicketId} allocated by {ActorId}: {AssetCount} asset(s), {DeviceCount} device(s), {KeyCount} key(s), {Credits} credits",
   155	            ticketId, actor.Id, results.Count,
   156	            results.Sum(r => r.Devices?.Count ?? 0), results.Sum(r => r.LicenseKeys?.Count ?? 0), results.Sum(r => r.Amount ?? 0m));
   157	
   158	        return Results.Ok(new AllocationResultDto(ticketId, TicketStatus.Allocated, now, results));
   159	    }
   160	
   161	    private static List<ShortageDto> FindShortages(List<TicketItem> items, Dictionary<Guid, Asset> assets)
   162	    {
   163	        var shortages = new List<ShortageDto>();
   164	        foreach (var item in items)
   165	        {
   166	            var asset = assets[item.AssetId];
   167	            var (requested, available) = asset.Type == AssetType.Voucher
   168	                ? (item.Amount ?? 0m, asset.Balance ?? 0m)
   169	                : (item.Quantity ?? 0, (decimal)(asset.RemainingUnits ?? 0));
   170	            if (requested > available)
   171	            {
   172	                shortages.Add(new ShortageDto(asset.Id, asset.Name, requested, available));
   173	            }
   174	        }
   175	        return shortages;
   176	    }
   177	
   178	    /// <summary>Rolls back anything pending, then logs the failed attempt (spec 6.13).</summary>
   179	    private async Task RecordFailureAsync(
   180	        Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction tx, Ticket ticket, Actor actor, DateTimeOffset now, string detail, CancellationToken ct)
   181	    {
   182	        await tx.RollbackAsync(ct);
   183	        db.ChangeTracker.Clear();
   184	        db.TicketEvents.Add(TicketEvents.Create(ticket.Id, TicketEventType.AllocationFailed, ticket.Status, ticket.Status, actor.Id, now, detail));
   185	        await db.SaveChangesAsync(ct);
   186	    }
   187	
   188	    /// <summary>Hardware assignment token: unguessable, so it can identify a device at return.</summary>
   189	    private static string NewToken() => "HW-" + Convert.ToHexString(RandomNumberGenerator.GetBytes(10));
   190	}
