    31	    /// <summary>One device per call, identified by its hardware assignment token (spec 6.11).</summary>
    32	    private static async Task<IResult> ReturnAsync(
    33	        Guid assetId, ReturnRequest body, HttpContext http, HubDbContext db, TimeProvider clock, ILogger<ReturnRequest> log, CancellationToken ct)
    34	    {
    35	        var (actor, denied) = await Actors.RequireAsync(http, db, ct, UserRole.Administrator);
    36	        if (denied is not null)
    37	        {
    38	            return denied;
    39	        }
    40	
    41	        var errors = new Errors();
    42	        var token = Validation.Text(errors, "token", body.Token, 40);
    43	        if (errors.Any)
    44	        {
    45	            return errors.ToResult();
    46	        }
    47	
    48	        await using var tx = await db.Database.BeginTransactionAsync(ct);
    49	        var asset = await db.Assets.FromSql($"SELECT * FROM assets WHERE \"Id\" = {assetId} FOR UPDATE").FirstOrDefaultAsync(ct);
    50	        if (asset is null)
    51	        {
    52	            return Problems.NotFound("Asset not found.");
    53	        }
    54	        if (asset.Type != AssetType.Physical)
    55	        {
    56	            return Problems.BadRequest("assetId", "Only physical devices are returned.");
    57	        }
    58	
    59	        var device = await db.DeviceAssignments.FirstOrDefaultAsync(d => d.Token == token && d.AssetId == assetId, ct);
    60	        if (device is null)
    61	        {
    62	            return Problems.NotFound("No device with this token was checked out from this asset.");
    63	        }
    64	        if (device.ReturnedAt is not null)
    65	        {
    66	            return Problems.Conflict("Device already returned.", $"It was returned at {device.ReturnedAt:O}.");
    67	        }
    68	
    69	        var now = clock.GetUtcNow();
    70	        device.ReturnedAt = now;
    71	        asset.RemainingUnits += 1;
    72	        asset.UpdatedAt = now;
    73	        await db.SaveChangesAsync(ct);
    74	        await tx.CommitAsync(ct);
    75	
    76	        var wasOverdue = now > device.DueAt;
    77	        log.LogInformation("Device {Token} of asset {AssetId} returned by {ActorId} (overdue: {Overdue})", token, assetId, actor!.Id, wasOverdue);
    78	
    79	        return Results.Ok(new ReturnResultDto(
    80	            device.Token, assetId, device.TicketId, device.CheckedOutAt, device.DueAt, now,
    81	            Math.Round((now - device.CheckedOutAt).TotalHours, 2), wasOverdue, asset.RemainingUnits!.Value));
    82	    }
    83	
    84	    /// <summary>Availability states a listing can be filtered by (spec requirement 2 and 6.3).</summary>
    85	    private enum AvailabilityFilter
    86	    {
    87	        Available,
    88	        Reserved,
    89	        Checkedout,
    90	        Overdue,
    91	    }
    92	
    93	    private static async Task<IResult> ListAsync(
    94	        HubDbContext db, TimeProvider clock, CancellationToken ct,
    95	        string? category = null, string? departmentProgram = null, string? availability = null,
    96	        string? type = null, string? search = null, int? page = null, int? pageSize = null)
    97	    {
    98	        var errors = new Errors();
    99	        var state = Query.Enum<AvailabilityFilter>(errors, "availability", availability);
   100	        var assetType = Query.Enum<AssetType>(errors, "type", type);
   101	        var (p, size) = Query.Paging(errors, page, pageSize);
   102	        if (errors.Any)
   103	        {
   104	            return errors.ToResult();
   105	        }
   106	
   107	        var now = clock.GetUtcNow();
   108	        var q = db.Assets.AsNoTracking();
   109	
   110	        if (!string.IsNullOrWhiteSpace(category))
   111	        {
   112	            var c = category.Trim().ToLower();
   113	            q = q.Where(a => a.Category.ToLower() == c);
   114	        }
   115	        if (!string.IsNullOrWhiteSpace(departmentProgram))
   116	        {
   117	            var d = departmentProgram.Trim().ToLower();
   118	            q = q.Where(a => a.DepartmentProgram.ToLower() == d);
   119	        }
   120	        if (!string.IsNullOrWhiteSpace(search))
   121	        {
   122	            var s = search.Trim().ToLower();
   123	            q = q.Where(a => a.Name.ToLower().Contains(s));
   124	        }
   125	        if (assetType is not null)
   126	        {
   127	            q = q.Where(a => a.Type == assetType);
   128	        }
   129	
   130	        q = state switch
   131	        {
   132	            // License and voucher assets count as available while stock or balance remains (spec 6.3).
   133	            AvailabilityFilter.Available => q.Where(a => a.RemainingUnits > 0 || a.Balance > 0),
   134	            AvailabilityFilter.Reserved => q.Where(a => a.Type == AssetType.Physical && db.TicketItems.Any(i =>
   135	                i.AssetId == a.Id && db.Tickets.Any(t => t.Id == i.TicketId && t.Status == TicketStatus.Approved))),
   136	            AvailabilityFilter.Checkedout => q.Where(a => db.DeviceAssignments.Any(d =>
   137	                d.AssetId == a.Id && d.ReturnedAt == null && d.DueAt >= now)),
   138	            AvailabilityFilter.Overdue => q.Where(a => db.DeviceAssignments.Any(d =>
   139	                d.AssetId == a.Id && d.ReturnedAt == null && d.DueAt < now)),
   140	            _ => q,
   141	        };
   142	
   143	        var total = await q.CountAsync(ct);
   144	        var items = await q
   145	            .OrderByDescending(a => a.CreatedAt).ThenBy(a => a.Id)
   146	            .Skip((p - 1) * size).Take(size)
   147	            .ToListAsync(ct);
   148	
   149	        return Results.Ok(new PagedResult<AssetDto>(await AssetViews.ToDtosAsync(db, items, now, ct), p, size, total));
   150	    }
