   152	    private static async Task<IResult> GetAsync(Guid assetId, HubDbContext db, TimeProvider clock, CancellationToken ct)
   153	    {
   154	        var asset = await db.Assets.AsNoTracking().FirstOrDefaultAsync(a => a.Id == assetId, ct);
   155	        return asset is null
   156	            ? Problems.NotFound("Asset not found.")
   157	            : Results.Ok(await AssetViews.ToDtoAsync(db, asset, clock.GetUtcNow(), ct));
   158	    }
