   160	    private static async Task<IResult> CreateAsync(
   161	        AssetRequest body, HttpContext http, HubDbContext db, TimeProvider clock, ILogger<AssetRequest> log, CancellationToken ct)
   162	    {
   163	        var (actor, denied) = await Actors.RequireAsync(http, db, ct, UserRole.Administrator);
   164	        if (denied is not null)
   165	        {
   166	            return denied;
   167	        }
   168	
   169	        var errors = new Errors();
   170	        var (name, category, department, keys) = Validation.Asset(errors, body);
   171	        if (errors.Any)
   172	        {
   173	            return errors.ToResult();
   174	        }
   175	
   176	        var now = clock.GetUtcNow();
   177	        var asset = new Asset
   178	        {
   179	            Id = Guid.NewGuid(),
   180	            Name = name,
   181	            Type = body.Type!.Value,
   182	            Category = category,
   183	            DepartmentProgram = department,
   184	            CreatedAt = now,
   185	            UpdatedAt = now,
   186	        };
   187	
   188	        switch (asset.Type)
   189	        {
   190	            case AssetType.Physical:
   191	                asset.TotalUnits = asset.RemainingUnits = body.Units;
   192	                asset.DefaultLoanDays = body.DefaultLoanDays;
   193	                break;
   194	            case AssetType.License:
   195	                asset.TotalUnits = asset.RemainingUnits = keys.Count;
   196	                asset.LicenseKeys = keys.Select(k => new LicenseKey { Id = Guid.NewGuid(), AssetId = asset.Id, Key = k }).ToList();
   197	                break;
   198	            case AssetType.Voucher:
   199	                asset.TotalBalance = asset.Balance = body.Balance;
   200	                break;
   201	        }
   202	
   203	        db.Assets.Add(asset);
   204	        await db.SaveChangesAsync(ct);
   205	        log.LogInformation("Asset {AssetId} ({Type}) created by {ActorId}", asset.Id, asset.Type, actor!.Id);
   206	
   207	        return Results.Created($"/api/v1/assets/{asset.Id}", await AssetViews.ToDtoAsync(db, asset, now, ct));
   208	    }
   209	
   210	    private static async Task<IResult> UpdateAsync(
   211	        Guid assetId, AssetRequest body, HttpContext http, HubDbContext db, TimeProvider clock, ILogger<AssetRequest> log, CancellationToken ct)
   212	    {
   213	        var (actor, denied) = await Actors.RequireAsync(http, db, ct, UserRole.Administrator);
   214	        if (denied is not null)
   215	        {
   216	            return denied;
   217	        }
   218	
   219	        var errors = new Errors();
   220	        var (name, category, department, keys) = Validation.Asset(errors, body);
   221	        if (errors.Any)
   222	        {
   223	            return errors.ToResult();
   224	        }
   225	
   226	        await using var tx = await db.Database.BeginTransactionAsync(ct);
   227	        // Lock the row so an allocation or return cannot change stock underneath this update.
   228	        var asset = await db.Assets
   229	            .FromSql($"SELECT * FROM assets WHERE \"Id\" = {assetId} FOR UPDATE")
   230	            .Include(a => a.LicenseKeys)
   231	            .FirstOrDefaultAsync(ct);
   232	        if (asset is null)
   233	        {
   234	            return Problems.NotFound("Asset not found.");
   235	        }
   236	        if (asset.Type != body.Type)
   237	        {
   238	            return Problems.BadRequest("type", "An asset's type cannot be changed.");
   239	        }
   240	
   241	        switch (asset.Type)
   242	        {
   243	            case AssetType.Physical:
   244	                {
   245	                    var handedOut = asset.TotalUnits!.Value - asset.RemainingUnits!.Value;
   246	                    if (body.Units < handedOut)
   247	                    {
   248	                        return Problems.Conflict("Total stock below units already handed out.",
   249	                            $"{handedOut} units are checked out; total stock cannot go below that.");
   250	                    }
   251	                    asset.TotalUnits = body.Units;
   252	                    asset.RemainingUnits = body.Units - handedOut;
   253	                    asset.DefaultLoanDays = body.DefaultLoanDays;
   254	                    break;
   255	                }
   256	            case AssetType.License:
   257	                {
   258	                    var wanted = keys.ToHashSet(StringComparer.Ordinal);
   259	                    var missingIssued = asset.LicenseKeys.Where(k => k.IssuedTicketId is not null && !wanted.Contains(k.Key)).ToList();
   260	                    if (missingIssued.Count > 0)
   261	                    {
   262	                        return Problems.Conflict("Issued license keys cannot be removed.",
   263	                            $"{missingIssued.Count} of the keys left out have already been issued.");
   264	                    }
   265	                    db.LicenseKeys.RemoveRange(asset.LicenseKeys.Where(k => k.IssuedTicketId is null && !wanted.Contains(k.Key)));
   266	                    var existing = asset.LicenseKeys.Select(k => k.Key).ToHashSet(StringComparer.Ordinal);
   267	                    foreach (var key in keys.Where(k => !existing.Contains(k)))
   268	                    {
   269	                        db.LicenseKeys.Add(new LicenseKey { Id = Guid.NewGuid(), AssetId = asset.Id, Key = key });
   270	                    }
   271	                    var issued = asset.LicenseKeys.Count(k => k.IssuedTicketId is not null);
   272	                    asset.TotalUnits = keys.Count;
   273	                    asset.RemainingUnits = keys.Count - issued;
   274	                    break;
   275	                }
   276	            case AssetType.Voucher:
   277	                {
   278	                    var used = asset.TotalBalance!.Value - asset.Balance!.Value;
   279	                    if (body.Balance < used)
   280	                    {
   281	                        return Problems.Conflict("Total credits below credits already allocated.",
   282	                            $"{used} credits are allocated; the total cannot go below that.");
   283	                    }
   284	                    asset.TotalBalance = body.Balance;
   285	                    asset.Balance = body.Balance - used;
   286	                    break;
   287	                }
   288	        }
   289	
   290	        asset.Name = name;
   291	        asset.Category = category;
   292	        asset.DepartmentProgram = department;
   293	        asset.UpdatedAt = clock.GetUtcNow();
   294	        await db.SaveChangesAsync(ct);
   295	        await tx.CommitAsync(ct);
   296	        log.LogInformation("Asset {AssetId} updated by {ActorId}", asset.Id, actor!.Id);
   297	
   298	        return Results.Ok(await AssetViews.ToDtoAsync(db, asset, clock.GetUtcNow(), ct));
   299	    }
   300	
   301	    private static async Task<IResult> DeleteAsync(
   302	        Guid assetId, HttpContext http, HubDbContext db, ILogger<AssetRequest> log, CancellationToken ct)
   303	    {
   304	        var (actor, denied) = await Actors.RequireAsync(http, db, ct, UserRole.Administrator);
   305	        if (denied is not null)
   306	        {
   307	            return denied;
   308	        }
   309	
   310	        var asset = await db.Assets.FirstOrDefaultAsync(a => a.Id == assetId, ct);
   311	        if (asset is null)
   312	        {
   313	            return Problems.NotFound("Asset not found.");
   314	        }
   315	
   316	        var referenced = await db.TicketItems.AnyAsync(i => i.AssetId == assetId, ct)
   317	                         || await db.Allocations.AnyAsync(a => a.AssetId == assetId, ct);
   318	        if (referenced)
   319	        {
   320	            return Problems.Conflict("Asset is in use.", "Tickets or allocations refer to this asset, so it cannot be deleted.");
   321	        }
   322	
   323	        db.Assets.Remove(asset);
   324	        await db.SaveChangesAsync(ct);
   325	        log.LogInformation("Asset {AssetId} deleted by {ActorId}", assetId, actor!.Id);
   326	        return Results.NoContent();
   327	    }
   328	}
