     9	using Microsoft.EntityFrameworkCore;
    10	using ResourceHub.Api.Contracts;
    11	using ResourceHub.Api.Data;
    12	using ResourceHub.Api.Domain;
    13	
    14	namespace ResourceHub.Api.Services;
    15	
    16	public static class AssetViews
    17	{
    18	    /// <summary>Builds DTOs for a set of assets with two grouped queries for the status counts.</summary>
    19	    public static async Task<List<AssetDto>> ToDtosAsync(
    20	        HubDbContext db, IReadOnlyList<Asset> assets, DateTimeOffset now, CancellationToken ct)
    21	    {
    22	        var physicalIds = assets.Where(a => a.Type == AssetType.Physical).Select(a => a.Id).ToList();
    23	
    24	        // Reserved: units requested on approved tickets that have not been allocated yet.
    25	        var reserved = await db.TicketItems
    26	            .Where(i => physicalIds.Contains(i.AssetId)
    27	                        && db.Tickets.Any(t => t.Id == i.TicketId && t.Status == TicketStatus.Approved))
    28	            .GroupBy(i => i.AssetId)
    29	            .Select(g => new { AssetId = g.Key, Units = g.Sum(i => i.Quantity ?? 0) })
    30	            .ToDictionaryAsync(x => x.AssetId, x => x.Units, ct);
    31	
    32	        var outstanding = await db.DeviceAssignments
    33	            .Where(d => physicalIds.Contains(d.AssetId) && d.ReturnedAt == null)
    34	            .GroupBy(d => d.AssetId)
    35	            .Select(g => new
    36	            {
    37	                AssetId = g.Key,
    38	                Overdue = g.Count(d => d.DueAt < now),
    39	                CheckedOut = g.Count(d => d.DueAt >= now),
    40	            })
    41	            .ToDictionaryAsync(x => x.AssetId, ct);
    42	
    43	        return assets.Select(a =>
    44	        {
    45	            var counts = outstanding.GetValueOrDefault(a.Id);
    46	            return ToDto(a, reserved.GetValueOrDefault(a.Id), counts?.CheckedOut ?? 0, counts?.Overdue ?? 0);
    47	        }).ToList();
    48	    }
    49	
    50	    public static async Task<AssetDto> ToDtoAsync(HubDbContext db, Asset asset, DateTimeOffset now, CancellationToken ct) =>
    51	        (await ToDtosAsync(db, [asset], now, ct))[0];
    52	
    53	    private static AssetDto ToDto(Asset a, int reserved, int checkedOut, int overdue)
    54	    {
    55	        var (total, remaining, availability) = a.Type switch
    56	        {
    57	            AssetType.Physical => (
    58	                (decimal)(a.TotalUnits ?? 0),
    59	                (decimal)(a.RemainingUnits ?? 0),
    60	                new AvailabilityDto(
    61	                    IsAvailable: a.RemainingUnits > 0,
    62	                    Available: a.RemainingUnits ?? 0,
    63	                    Reserved: reserved,
    64	                    Checkedout: checkedOut,
    65	                    Overdue: overdue)),
    66	            AssetType.License => (
    67	                (decimal)(a.TotalUnits ?? 0),
    68	                (decimal)(a.RemainingUnits ?? 0),
    69	                new AvailabilityDto(
    70	                    IsAvailable: a.RemainingUnits > 0,
    71	                    Available: a.RemainingUnits ?? 0,
    72	                    Issued: (a.TotalUnits ?? 0) - (a.RemainingUnits ?? 0))),
    73	            _ => (
    74	                a.TotalBalance ?? 0m,
    75	                a.Balance ?? 0m,
    76	                new AvailabilityDto(
    77	                    IsAvailable: a.Balance > 0m,
    78	                    Balance: a.Balance ?? 0m,
    79	                    Allocated: (a.TotalBalance ?? 0m) - (a.Balance ?? 0m))),
    80	        };
    81	
    82	        return new AssetDto(
    83	            a.Id, a.Name, a.Type, a.Category, a.DepartmentProgram,
    84	            total, remaining, a.DefaultLoanDays, availability, a.CreatedAt, a.UpdatedAt);
    85	    }
    86	}

