    15	/// <summary>Collects field errors and turns them into a 400 validation problem.</summary>
    16	public sealed class Errors
    17	{
    18	    private readonly Dictionary<string, List<string>> _errors = [];
    19	
    20	    public bool Any => _errors.Count > 0;
    21	
    22	    public void Add(string field, string message)
    23	    {
    24	        if (!_errors.TryGetValue(field, out var list))
    25	        {
    26	            _errors[field] = list = [];
    27	        }
    28	        list.Add(message);
    29	    }
