    35	    {
    36	        if (string.IsNullOrWhiteSpace(raw))
    37	        {
    38	            return null;
    39	        }
    40	        foreach (var value in System.Enum.GetValues<TEnum>())
    41	        {
    42	            if (string.Equals(JsonNamingPolicy.SnakeCaseLower.ConvertName(value.ToString()), raw.Trim(), StringComparison.OrdinalIgnoreCase))
    43	            {
    44	                return value;
    45	            }
    46	        }
    47	        var allowed = string.Join(", ", System.Enum.GetValues<TEnum>().Select(v => JsonNamingPolicy.SnakeCaseLower.ConvertName(v.ToString())));
    48	        errors.Add(field, $"Must be one of: {allowed}.");
    49	        return null;
    50	    }
    51	}
