    39	    public static async Task<HttpResponseMessage> SendAsync(
    40	        this HttpClient client, HttpMethod method, string url, object? body = null, Guid? user = null)
    41	    {
    42	        using var request = new HttpRequestMessage(method, url);
    43	        if (body is string raw)
    44	        {
    45	            // Raw JSON text, for malformed or hand-written bodies.
    46	            request.Content = new StringContent(raw, System.Text.Encoding.UTF8, "application/json");
    47	        }
    48	        else if (body is not null)
    49	        {
    50	            request.Content = JsonContent.Create(body);
    51	        }
    52	        if (user is not null)
    53	        {
    54	            request.Headers.Add(UserHeader, user.Value.ToString());
    55	        }
    56	        return await client.SendAsync(request);
    57	    }
