    17	/// <summary>A clock the tests can move forward (for due dates and overdue devices).</summary>
    18	public sealed class TestClock : TimeProvider
    19	{
    20	    private DateTimeOffset _now = new(2026, 11, 14, 9, 0, 0, TimeSpan.Zero);
