    22	    public override DateTimeOffset GetUtcNow() => _now;
    23	
    24	    public void Advance(TimeSpan by) => _now = _now.Add(by);
    25	}
    26	
    27	/// <summary>
    28	/// Runs the API in memory against its own PostgreSQL database, created (and migrated and
    29	/// seeded) at startup and dropped when the test class finishes.
    30	/// </summary>
    31	public class HubApiFactory : WebApplicationFactory<Program>, IAsyncLifetime
    32	{
    33	    private readonly string _databaseName = $"rh_test_{Guid.NewGuid():N}";
    34	
    35	    public TestClock Clock { get; } = new();
    36	
    37	    protected virtual string ConnectionString => TestDb.ForDatabase(_databaseName);
    38	
    39	    protected override void ConfigureWebHost(IWebHostBuilder builder)
    40	    {
    41	        builder.UseEnvironment("Testing");
    42	        builder.UseSetting("ConnectionStrings:HubDb", ConnectionString);
    43	        builder.ConfigureServices(services =>
    44	        {
    45	            services.RemoveAll<TimeProvider>();
    46	            services.AddSingleton<TimeProvider>(Clock);
    47	        });
    48	    }
    49	
    50	    public virtual Task InitializeAsync()
    51	    {
    52	        // Starting the host applies the migrations and seed data.
    53	        _ = Server;
    54	        return Task.CompletedTask;
    55	    }
    56	
    57	    async Task IAsyncLifetime.DisposeAsync()
    58	    {
    59	        await base.DisposeAsync();
    60	        if (TestDb.BaseConnectionString is null)
    61	        {
    62	            return;
    63	        }
    64	
    65	        NpgsqlConnection.ClearAllPools();
    66	        await using var connection = new NpgsqlConnection(TestDb.BaseConnectionString);
    67	        await connection.OpenAsync();
    68	        await using var command = connection.CreateCommand();
    69	        // The name is generated above from a GUID, never from input.
    70	        command.CommandText = $"DROP DATABASE IF EXISTS \"{_databaseName}\" WITH (FORCE)";
    71	        await command.ExecuteNonQueryAsync();
    72	    }
    73	}
